    "name": "public/release.js",
    "sha256": "fe087c230774f3573e6870a8d066f3c9a83cb658a3eab27f176a6225b1cf3fc3",
    "encoding": "utf8",
    "content": "export const BUILD_ID='43.2.0';\nexport const BUILD_LABEL='Ben 10 · Clareira LIVE · 43.2.0';\n"
