  {
    "name": "scripts/local-ai/clone.sh",
    "sha256": "8ee0f5bb9d03c8795d85506342514dd48c91cdb44726b99e6e9520903c1d00f3",
    "encoding": "utf8",
    "content": "#!/usr/bin/env bash\nset -euo pipefail\ntask_game_root=\"$(cd -- \"$(dirname -- \"$0\")/../..\" && pwd)\"\ntask_local_root=\"${BEN10_LOCAL_ROOT:-$HOME/.local/share/ben10-local-ai}\"\ntask_command=\"${1:-help}\"; shift || true\ncase \"$task_command\" in\n setup)\n  exec python3 \"$task_game_root/scripts/local-ai/clone_setup.py\" --root \"$task_local_root\" --game \"$task_game_root\"\n  ;;\n repair-native)\n  exec python3 \"$task_game_root/scripts/local-ai/clone_native.py\" --root \"$task_local_root\"\n  ;;\n install)\n  [[ -f \"$task_local_root/install.json\" ]] || { printf 'Instale primeiro a IA existente: bash local-ai.sh install\\n' >&2; exit 1; }\n  command -v pkg >/dev/null && [[ \"$(uname -m)\" == aarch64 ]] || { printf 'Este instalador é para Termux ARM64.\\n' >&2; exit 1; }\n  printf 'Clonagem experimental Qwen3-TTS 0.6B. A instalação inicial usa internet e vários GB; a velocidade precisa ser medida no aparelho.\\n'\n  bash \"$task_game_root/scripts/termux-packages.sh\" git cmake ninja clang python proot-distro\n  python3 \"$task_game_root/scripts/local-ai/clone_models.py\" --root \"$task_local_root/cloning\"\n  task_clone_source=\"$task_local_root/qwen3-tts.cpp\"\n  task_clone_revision=b3ba14077cf1b3e11b86e5f84aa9184605c89b28\n  if [[ ! -d \"$task_clone_source/.git\" ]]; then\n    git init \"$task_clone_source\"\n    git -C \"$task_clone_source\" remote add origin https://github.com/predict-woo/qwen3-tts.cpp.git\n  fi\n  git -C \"$task_clone_source\" fetch --depth 1 origin \"$task_clone_revision\"\n  git -C \"$task_clone_source\" checkout --detach \"$task_clone_revision\"\n  git -C \"$task_clone_source\" submodule update --init --depth 1 --recursive\n  python3 \"$task_game_root/scripts/local-ai/clone_native.py\" --root \"$task_local_root\"\n  # CPU PyTorch is used only for the one-time source-weight conversion in Debian.\n  proot-distro login --bind \"$task_local_root:/ben10-data\" --bind \"$task_game_root/scripts/local-ai:/opt/ben10-clone-worker\" ben10-ai -- /bin/bash -lc '\nset -euo pipefail\npython3 -m venv /opt/ben10-clone-convert\n/opt/ben10-clone-convert/bin/pip install --disable-pip-version-check --only-binary=:all: -r /opt/ben10-clone-worker/clone-convert-requirements.txt\nmkdir -p /ben10-data/cloning/models\n/opt/ben10-clone-convert/bin/python /ben10-data/qwen3-tts.cpp/scripts/convert_tts_to_gguf.py --input /ben10-data/cloning/source --output /ben10-data/cloning/models/qwen3-tts-0.6b-f16.gguf.part --type f16\n/opt/ben10-clone-convert/bin/python /ben10-data/qwen3-tts.cpp/scripts/convert_tokenizer_to_gguf.py --input /ben10-data/cloning/source/speech_tokenizer --output /ben10-data/cloning/models/qwen3-tts-tokenizer-f16.gguf.part --type f16\nmv /ben10-data/cloning/models/qwen3-tts-0.6b-f16.gguf.part /ben10-data/cloning/models/qwen3-tts-0.6b-f16.gguf\nmv /ben10-data/cloning/models/qwen3-tts-tokenizer-f16.gguf.part /ben10-data/cloning/models/qwen3-tts-tokenizer-f16.gguf\n'\n  printf 'Motor nativo preparado. A voz atual foi mantida. Falta a amostra: bash local-ai.sh clone reference caminho/ben.wav\\n'\n  ;;\n reference|use|piper|status)\n  exec python3 \"$task_game_root/scripts/local-ai/clone_config.py\" --root \"$task_local_root\" \"$task_command\" \"$@\"\n  ;;\n preview)\n  exec python3 \"$task_game_root/scripts/local-ai/clone_voice.py\" --root \"$task_local_root\" --preview \"$task_local_root/cloning/preview.wav\"\n  ;;\n *) printf 'Preparar com áudio do Ben incluído: bash local-ai.sh clone setup\\nReparar SIGILL sem baixar modelos: bash local-ai.sh clone repair-native\\nInstalar motor/modelos ausentes: bash local-ai.sh clone install\\nOutra amostra: bash local-ai.sh clone reference caminho/ben.wav\\nOuvir teste: bash local-ai.sh clone preview\\nUsar clone: bash local-ai.sh clone use\\nVoltar ao Piper: bash local-ai.sh clone piper\\nEstado: bash local-ai.sh clone status\\n' ;;\nesac\n"
