  {
    "name": "scripts/local-ai/clone_native.py",
    "sha256": "68deff4748f83efa3722d8683f7446f890d50b1cb6c79abca455339efbab3913",
    "encoding": "utf8",
    "content": "\"\"\"Rebuild only the native clone engine with portable CPU instructions.\"\"\"\nimport argparse\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport platform\nimport re\nimport shutil\nimport subprocess\nimport tempfile\n\nPROFILE = \"ben10-portable-v1\"\nREVISION = \"b3ba14077cf1b3e11b86e5f84aa9184605c89b28\"\nGGML_REVISION = \"3af5f5760e19a96427f5f7a93b79cbdf3d4b265b\"\n\n\ndef cpu_profile(machine=None):\n    machine = (machine or platform.machine()).lower()\n    if machine in (\"aarch64\", \"arm64\"):\n        return \"aarch64\", \"-march=armv8-a\"\n    if machine in (\"x86_64\", \"amd64\"):\n        return \"x86_64\", \"-march=x86-64 -mtune=generic\"\n    raise ValueError(\"Arquitetura não suportada pelo perfil de reparo: \" + machine)\n\n\ndef digest(path):\n    result = hashlib.sha256()\n    with Path(path).open(\"rb\") as source:\n        for chunk in iter(lambda: source.read(1024 * 1024), b\"\"):\n            result.update(chunk)\n    return result.hexdigest()\n\n\ndef portable_ready(root):\n    root = Path(root)\n    try:\n        record = json.loads((root / \"cloning/native-build.json\").read_text())\n        machine, flags = cpu_profile()\n        if record.get(\"profile\") != PROFILE or record.get(\"machine\") != machine or record.get(\"flags\") != flags:\n            return False\n        files = record.get(\"files\", {})\n        if \"qwen3-tts.cpp/build/libqwen3tts.so\" not in files:\n            return False\n        for name, expected in files.items():\n            relative = Path(name)\n            if relative.is_absolute() or \"..\" in relative.parts or not (root / relative).is_file() or digest(root / relative) != expected:\n                return False\n        return True\n    except (OSError, ValueError, TypeError, AttributeError):\n        return False\n\n\ndef patch_native_flags(text):\n    # Upstream appends these even when CMAKE_CXX_FLAGS was explicitly supplied.\n    return re.sub(r\"-(?:march|mcpu|mtune)=native\\b\", \"\", text)\n\n\ndef build_commands(source, flags, cmake=\"cmake\"):\n    source = Path(source)\n    common = [\"-G\", \"Ninja\", \"-DCMAKE_BUILD_TYPE=Release\", \"-DCMAKE_EXPORT_COMPILE_COMMANDS=ON\",\n              \"-DCMAKE_C_FLAGS=\" + flags, \"-DCMAKE_CXX_FLAGS=\" + flags,\n              \"-DCMAKE_C_FLAGS_RELEASE=-O3 -DNDEBUG\", \"-DCMAKE_CXX_FLAGS_RELEASE=-O3 -DNDEBUG\"]\n    x86 = [\"-DGGML_AVX=OFF\", \"-DGGML_AVX2=OFF\", \"-DGGML_AVX512=OFF\", \"-DGGML_FMA=OFF\", \"-DGGML_F16C=OFF\", \"-DGGML_SSSE3=OFF\"] if flags.startswith(\"-march=x86-64\") else []\n    return [\n        [cmake, \"--fresh\", \"-S\", str(source / \"ggml\"), \"-B\", str(source / \"ggml/build\"), *common,\n         \"-DGGML_NATIVE=OFF\", \"-DGGML_CPU_ARM_ARCH=armv8-a\", \"-DGGML_CPU_KLEIDIAI=OFF\",\n         \"-DGGML_CPU_ALL_VARIANTS=OFF\", \"-DGGML_BACKEND_DL=OFF\", \"-DGGML_METAL=OFF\",\n         \"-DGGML_OPENMP=OFF\", \"-DGGML_BUILD_TESTS=OFF\", \"-DGGML_BUILD_EXAMPLES=OFF\", *x86],\n        [cmake, \"--build\", str(source / \"ggml/build\"), \"--parallel\", \"4\"],\n        [cmake, \"--fresh\", \"-S\", str(source), \"-B\", str(source / \"build\"), *common,\n         \"-DQWEN3_TTS_COREML=OFF\"],\n        [cmake, \"--build\", str(source / \"build\"), \"--target\", \"qwen3tts_shared\", \"--parallel\", \"4\"],\n    ]\n\n\ndef check_compile_commands(source, machine):\n    commands = []\n    for directory in [Path(source) / \"build\", Path(source) / \"ggml/build\"]:\n        records = json.loads((directory / \"compile_commands.json\").read_text())\n        for record in records:\n            command = record.get(\"command\") or \" \".join(record.get(\"arguments\", []))\n            if re.search(r\"-(?:march|mcpu|mtune)=native\\b\", command):\n                raise ValueError(\"A compilação ainda contém otimização nativa\")\n            if machine == \"aarch64\":\n                if \"-march=armv8-a\" not in command or re.search(r\"\\+(?:sve\\w*|sme\\w*|i8mm|dotprod|fp16)\", command):\n                    raise ValueError(\"A compilação ARM contém instruções fora da base ARMv8-A\")\n            commands.append(command)\n    if not commands:\n        raise ValueError(\"Não foi possível conferir os comandos da compilação\")\n    return len(commands)\n\n\ndef rebuild(root, run=subprocess.run, machine=None, cmake=\"cmake\", verify_source=True):\n    root = Path(root).resolve(); source = root / \"qwen3-tts.cpp\"\n    machine, flags = cpu_profile(machine)\n    if not (source / \"CMakeLists.txt\").is_file() or not (source / \"ggml/CMakeLists.txt\").is_file():\n        raise ValueError(\"Fontes nativas ausentes. Complete bash local-ai.sh clone install\")\n    if verify_source:\n        for directory, expected in [(source, REVISION), (source / \"ggml\", GGML_REVISION)]:\n            actual = subprocess.check_output([\"git\", \"-C\", str(directory), \"rev-parse\", \"HEAD\"], text=True).strip()\n            if actual != expected:\n                raise ValueError(\"A revisão das fontes mudou; nenhum arquivo foi recompilado\")\n    folder = root / \"cloning\"; folder.mkdir(parents=True, exist_ok=True)\n    backup = Path(tempfile.mkdtemp(prefix=\"native-before-repair-\", dir=folder))\n    cmake_file = source / \"CMakeLists.txt\"\n    shutil.copyfile(cmake_file, backup / \"CMakeLists.txt\")\n    for label, directory in [(\"engine\", source / \"build\"), (\"ggml\", source / \"ggml/build\")]:\n        for name in [\"CMakeCache.txt\", \"compile_commands.json\"]:\n            if (directory / name).is_file():\n                shutil.copyfile(directory / name, backup / (label + \"-\" + name))\n    cmake_file.write_text(patch_native_flags(cmake_file.read_text()))\n    print(\"Reconstruindo somente o motor da voz:\", flags, flush=True)\n    print(\"Modelos GGUF, referência, chaves e motor de conversa serão preservados.\", flush=True)\n    environment = {**os.environ, \"QWEN3_TTS_BACKEND\": \"cpu\"}\n    for command in build_commands(source, flags, cmake):\n        run(command, check=True, env=environment)\n    checked = check_compile_commands(source, machine)\n    binaries = [source / \"build/libqwen3tts.so\"]\n    binaries += sorted((source / \"ggml/build/src\").glob(\"lib*.so*\"))\n    if any(not binary.is_file() for binary in binaries):\n        raise ValueError(\"A reconstrução não gerou todas as bibliotecas\")\n    record = {\"profile\": PROFILE, \"machine\": machine, \"flags\": flags,\n              \"revision\": REVISION, \"ggmlRevision\": GGML_REVISION, \"commandsChecked\": checked,\n              \"files\": {str(file.relative_to(root)): digest(file) for file in binaries}}\n    temp = folder / \"native-build.json.tmp\"; temp.write_text(json.dumps(record, indent=2))\n    os.replace(temp, folder / \"native-build.json\")\n    print(\"Motor portátil reconstruído. Opções antigas guardadas em\", backup, flush=True)\n    return record\n\n\nif __name__ == \"__main__\":\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"--root\", required=True, type=Path)\n    args = parser.parse_args()\n    try:\n        rebuild(args.root)\n    except Exception as error:\n        raise SystemExit(\"Motor não reparado: \" + str(error))\n"
  },
