    "name": "scripts/local-ai/clone_setup.py",
    "sha256": "dd10d7dc62a566eb6c5372ff28d4cd8ce5d5dbff4616038e50e8df2f786c39a7",
    "encoding": "utf8",
    "content": "\"\"\"Install, register the bundled reference, test real synthesis and select atomically.\"\"\"\nimport argparse\nimport hashlib\nimport json\nimport math\nimport os\nfrom pathlib import Path\nimport shutil\nimport signal\nimport socket\nimport subprocess\nimport sys\nimport tempfile\nimport wave\nfrom clone_config import configure\nfrom clone_native import portable_ready\n\nOWNED = (\"reference.wav\", \"config.json\", \"preview.wav\", \"preview.json\")\n\n\ndef check_bundle(game):\n    folder = Path(game) / \"assets/voice\"\n    metadata = json.loads((folder / \"ben-classico-reference.json\").read_text())\n    reference = folder / \"ben-classico-reference.wav\"\n    if metadata.get(\"file\") != reference.name or hashlib.sha256(reference.read_bytes()).hexdigest() != metadata.get(\"sha256\"):\n        raise ValueError(\"A referência de voz do pacote não passou na conferência de integridade\")\n    with wave.open(str(reference)) as wav:\n        if (wav.getframerate(), wav.getnchannels(), wav.getsampwidth()) != (24000, 1, 2) or not 3 <= wav.getnframes() / wav.getframerate() <= 30:\n            raise ValueError(\"Referência de voz inválida\")\n    return reference\n\n\ndef installed(root):\n    root = Path(root)\n    return portable_ready(root) and models_ready(root)\n\n\ndef models_ready(root):\n    root = Path(root)\n    for filename in [\"qwen3-tts-0.6b-f16.gguf\", \"qwen3-tts-tokenizer-f16.gguf\"]:\n        file = root / \"cloning/models\" / filename\n        if not file.is_file():\n            return False\n        with file.open(\"rb\") as source:\n            if source.read(4) != b\"GGUF\":\n                return False\n    return True\n\n\ndef check_ports():\n    for port in (8081, 8082):\n        with socket.socket() as connection:\n            connection.settimeout(.5)\n            if connection.connect_ex((\"127.0.0.1\", port)) == 0:\n                raise ValueError(\"Pare a sessão da IA com Ctrl+C antes de preparar a clonagem\")\n\n\ndef setup(root, game, run=subprocess.run, probe=check_ports):\n    root, game = Path(root).resolve(), Path(game).resolve()\n    reference = check_bundle(game)  # Fail before downloads, conversion or selection.\n    manifest_file = root / \"install.json\"\n    manifest_bytes = manifest_file.read_bytes()\n    json.loads(manifest_bytes)\n    probe()\n    folder = root / \"cloning\"\n    folder.mkdir(parents=True, exist_ok=True)\n    backup = Path(tempfile.mkdtemp(prefix=\"setup-\", dir=folder))\n    previous = {}\n    child_environment = {**os.environ, \"BEN10_LOCAL_ROOT\": str(root)}\n    child_environment[\"QWEN3_TTS_BACKEND\"] = \"cpu\"\n    preview_log = root / \"logs/clonagem-preview.log\"\n    preview_log.parent.mkdir(parents=True, exist_ok=True)\n    for name in OWNED:\n        path = folder / name\n        previous[name] = path.is_file()\n        if path.is_file():\n            shutil.copyfile(path, backup / name)\n    try:\n        if not installed(root):\n            command = \"repair-native\" if models_ready(root) else \"install\"\n            print(\"Reconstruindo o motor; os modelos convertidos serão reutilizados.\" if command == \"repair-native\" else \"Preparando o motor e os modelos da clonagem…\", flush=True)\n            run([\"bash\", str(game / \"scripts/local-ai/clone.sh\"), command], check=True, env=child_environment)\n        else:\n            print(\"Motor já instalado. Sem reinstalar ou consultar catálogos.\", flush=True)\n        configure(root, \"reference\", reference)\n        print(\"Gerando um teste real com a referência do Ben. O tempo depende do aparelho…\", flush=True)\n        with preview_log.open(\"w\") as output:\n            run([sys.executable, \"-X\", \"faulthandler\", str(game / \"scripts/local-ai/clone_voice.py\"), \"--root\", str(root), \"--preview\", str(folder / \"preview.wav\")], check=True, timeout=600, env=child_environment, stdout=output, stderr=subprocess.STDOUT)\n        # A partial file or an old preview cannot qualify as a successful setup.\n        preview = json.loads((folder / \"preview.json\").read_text())\n        if preview.get(\"referenceSha256\") != hashlib.sha256((folder / \"reference.wav\").read_bytes()).hexdigest():\n            raise ValueError(\"O teste não corresponde à referência atual\")\n        elapsed = preview.get(\"secondsToGenerate\")\n        if not isinstance(elapsed, (int, float)) or not math.isfinite(elapsed) or elapsed <= 0 or elapsed > 150:\n            raise ValueError(\"A geração excedeu o tempo permitido para esse perfil; a voz anterior será mantida\")\n        with wave.open(str(folder / \"preview.wav\")) as wav:\n            if wav.getframerate() != 24000 or wav.getnchannels() != 1 or wav.getnframes() < 240:\n                raise ValueError(\"O teste de voz não gerou um WAV válido\")\n        configure(root, \"use\")\n        print(\"Clonagem selecionada após síntese real. Preview:\", folder / \"preview.wav\", flush=True)\n        print(\"Tempo para gerar a frase:\", elapsed, \"s. Agora execute bash local-ai.sh start\", flush=True)\n        return {\"selected\": True, \"secondsToGenerate\": elapsed, \"preview\": str(folder / \"preview.wav\")}\n    except BaseException as error:\n        temp = manifest_file.with_suffix(\".restore.tmp\")\n        temp.write_bytes(manifest_bytes); os.replace(temp, manifest_file)\n        for name, existed in previous.items():\n            destination = folder / name\n            if existed:\n                shutil.copyfile(backup / name, destination)\n            else:\n                destination.unlink(missing_ok=True)\n        print(\"A preparação não terminou. A seleção e a referência anteriores foram restauradas.\", flush=True)\n        if isinstance(error, subprocess.CalledProcessError) and error.returncode == -signal.SIGILL:\n            raise RuntimeError(\"O motor encerrou com SIGILL. Execute bash local-ai.sh clone repair-native e repita o setup. Diagnóstico em \" + str(preview_log)) from error\n        raise\n    finally:\n        shutil.rmtree(backup)\n\n\nif __name__ == \"__main__\":\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"--root\", required=True, type=Path)\n    parser.add_argument(\"--game\", required=True, type=Path)\n    args = parser.parse_args()\n    try:\n        setup(args.root, args.game)\n    except Exception as error:\n        raise SystemExit(\"Clonagem não ativada: \" + str(error))\n"
  },
  {
    "name": "scripts/local-ai/clone_voice.py",
    "sha256": "fe24b3f17c6a8a87d230e172f2888d501f38c7dd4e17defb2f08e68b67bfc8ae",
    "encoding": "utf8",
    "content": "\"\"\"Qwen3-TTS C API bridge. Native inference, local reference, no Python ML runtime.\"\"\"\nimport argparse\nimport array\nimport ctypes as c\nimport json\nimport math\nimport sys\nimport wave\nimport hashlib\nimport faulthandler\nimport os\nfrom pathlib import Path\nfrom tts_server import make_server\n\n\nclass Params(c.Structure):\n    _fields_ = [(\"max_audio_tokens\", c.c_int32), (\"temperature\", c.c_float),\n                (\"top_p\", c.c_float), (\"top_k\", c.c_int32), (\"n_threads\", c.c_int32),\n                (\"repetition_penalty\", c.c_float), (\"language_id\", c.c_int32)]\n\n\nclass Audio(c.Structure):\n    _fields_ = [(\"samples\", c.POINTER(c.c_float)), (\"n_samples\", c.c_int32), (\"sample_rate\", c.c_int32)]\n\n\ndef configure_reference(source, target):\n    \"\"\"Accept PCM16 WAV; downmix/resample locally, without external decoders.\"\"\"\n    source, target = Path(source), Path(target)\n    if source.stat().st_size > 16 * 1024**2:\n        raise ValueError(\"Use um WAV de até 30 segundos e 16 MB\")\n    with wave.open(str(source), \"rb\") as wav:\n        channels, rate, frames = wav.getnchannels(), wav.getframerate(), wav.getnframes()\n        if wav.getsampwidth() != 2 or channels not in (1, 2) or not 8000 <= rate <= 96000 or not 3 <= frames / rate <= 30:\n            raise ValueError(\"Amostra: WAV PCM16, mono/estéreo, 3 a 30 segundos\")\n        data = array.array(\"h\", wav.readframes(frames))\n    if sys.byteorder != \"little\":\n        data.byteswap()\n    if len(data) != frames * channels:\n        raise ValueError(\"WAV incompleto\")\n    mono = data if channels == 1 else array.array(\"h\", ((data[i] + data[i + 1]) // 2 for i in range(0, len(data), 2)))\n    if max(abs(v) for v in mono) < 120:\n        raise ValueError(\"A amostra está silenciosa ou muito baixa\")\n    output = array.array(\"h\")\n    for i in range(round(len(mono) * 24000 / rate)):\n        position = i * rate / 24000\n        a = min(int(position), len(mono) - 1)\n        b = min(a + 1, len(mono) - 1)\n        output.append(round(mono[a] + (mono[b] - mono[a]) * (position - a)))\n    if sys.byteorder != \"little\":\n        output.byteswap()\n    target.parent.mkdir(parents=True, exist_ok=True)\n    temp = target.with_suffix(\".tmp.wav\")\n    with wave.open(str(temp), \"wb\") as wav:\n        wav.setnchannels(1); wav.setsampwidth(2); wav.setframerate(24000); wav.writeframes(output.tobytes())\n    temp.replace(target)\n    return {\"seconds\": frames / rate, \"sampleRate\": 24000, \"channels\": 1}\n\n\nclass CloneVoice:\n    def __init__(self, library, models, reference, threads=4, loader=c.CDLL, progress=None):\n        self.progress = progress or (lambda message: None)\n        self.progress(\"Carregando biblioteca nativa\")\n        self.lib = loader(str(library))\n        self.handle = None\n        api = self.lib\n        signatures = {\n            \"qwen3_tts_create\": ([c.c_char_p, c.c_int32], c.c_void_p),\n            \"qwen3_tts_destroy\": ([c.c_void_p], None),\n            \"qwen3_tts_default_params\": ([c.POINTER(Params)], None),\n            \"qwen3_tts_extract_embedding_file\": ([c.c_void_p, c.c_char_p, c.POINTER(c.c_float), c.c_int32], c.c_int32),\n            \"qwen3_tts_synthesize_with_embedding\": ([c.c_void_p, c.c_char_p, c.POINTER(c.c_float), c.c_int32, c.POINTER(Params)], c.POINTER(Audio)),\n            \"qwen3_tts_free_audio\": ([c.POINTER(Audio)], None),\n            \"qwen3_tts_get_error\": ([c.c_void_p], c.c_char_p),\n        }\n        for name, (args, result) in signatures.items():\n            fn = getattr(api, name); fn.argtypes = args; fn.restype = result\n        self.progress(\"Carregando os modelos GGUF\")\n        self.handle = api.qwen3_tts_create(str(models).encode(), threads)\n        if not self.handle:\n            raise ValueError(\"Qwen3-TTS não carregou os GGUF. Consulte logs/voz.log\")\n        self.embedding = (c.c_float * 4096)()\n        self.progress(\"Extraindo a voz da referência\")\n        self.embedding_size = api.qwen3_tts_extract_embedding_file(self.handle, str(reference).encode(), self.embedding, 4096)\n        if not 1 <= self.embedding_size <= 4096:\n            self.close()\n            raise ValueError(\"Não foi possível extrair a voz da amostra\")\n        self.params = Params(); api.qwen3_tts_default_params(c.byref(self.params))\n        self.params.language_id = 2071  # Portuguese; never leave the default English token.\n        self.params.n_threads = threads\n        self.params.max_audio_tokens = 384\n        self.params.temperature = 0.6\n\n    def close(self):\n        if self.handle:\n            self.lib.qwen3_tts_destroy(self.handle); self.handle = None\n\n    def synthesize_wav(self, text, output):\n        self.progress(\"Gerando áudio em português\")\n        result = self.lib.qwen3_tts_synthesize_with_embedding(self.handle, text.encode(), self.embedding, self.embedding_size, c.byref(self.params))\n        if not result:\n            raise ValueError(\"A clonagem não gerou áudio\")\n        try:\n            audio = result.contents\n            if audio.sample_rate != 24000 or not 240 <= audio.n_samples <= 24000 * 35 or not audio.samples:\n                raise ValueError(\"Áudio clonado inválido ou longo demais\")\n            pcm = array.array(\"h\")\n            for i in range(audio.n_samples):\n                value = audio.samples[i]\n                if not math.isfinite(value):\n                    raise ValueError(\"Áudio clonado inválido\")\n                pcm.append(round(max(-1, min(1, value)) * 32767))\n            if not any(abs(v) > 20 for v in pcm):\n                raise ValueError(\"A clonagem gerou silêncio\")\n            if sys.byteorder != \"little\":\n                pcm.byteswap()\n            output.setnchannels(1); output.setsampwidth(2); output.setframerate(24000); output.writeframes(pcm.tobytes())\n        finally:\n            self.lib.qwen3_tts_free_audio(result)\n\n\ndef main():\n    faulthandler.enable(all_threads=True)\n    os.environ[\"QWEN3_TTS_BACKEND\"] = \"cpu\"\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\"--root\", type=Path, required=True)\n    parser.add_argument(\"--port\", type=int, default=8082)\n    parser.add_argument(\"--preview\", type=Path)\n    args = parser.parse_args()\n    if not 1024 <= args.port <= 65535:\n        parser.error(\"Porta inválida\")\n    root = args.root.resolve()\n    config = json.loads((root / \"cloning/config.json\").read_text())\n    voice = CloneVoice(root / \"qwen3-tts.cpp/build/libqwen3tts.so\", root / \"cloning/models\", root / \"cloning/reference.wav\", progress=lambda message: print(message, file=sys.stderr, flush=True))\n    try:\n        if args.preview:\n            import time\n            started = time.monotonic()\n            preview_temp = args.preview.with_suffix(\".tmp.wav\")\n            try:\n                with wave.open(str(preview_temp), \"wb\") as wav:\n                    voice.synthesize_wav(\"E aí, pessoal! Agora o relógio está pronto. Quatro Braços corre rápido!\", wav)\n                preview_temp.replace(args.preview)\n            finally:\n                preview_temp.unlink(missing_ok=True)\n            latency = round(time.monotonic() - started, 2)\n            result = {\"preview\": str(args.preview), \"secondsToGenerate\": latency, \"reference\": config.get(\"seconds\"), \"referenceSha256\": hashlib.sha256((root / \"cloning/reference.wav\").read_bytes()).hexdigest(), \"language\": \"Portuguese\"}\n            (root / \"cloning/preview.json\").write_text(json.dumps(result))\n            print(json.dumps(result))\n            return\n        server = make_server(voice, args.port, model_name=\"Qwen3-TTS-0.6B-clone-pt\")\n        print(f\"Clonagem pronta em 127.0.0.1:{args.port}; referência local carregada\", flush=True)\n        try:\n            server.serve_forever()\n        finally:\n            server.server_close()\n    finally:\n        voice.close()\n\n\nif __name__ == \"__main__\":\n    main()\n"
  }
];
try {
 const [stage,root]=process.argv.slice(2);
 const pkg=JSON.parse(await readFile(path.join(root,'package.json'),'utf8'));
 if(pkg.name!=='linel-live-city'||!/^43\.[12]\./.test(pkg.version))throw Error('Este reparo é para a V43.1 ou V43.2 do Ben. Entre na pasta correta do jogo.');
 await writeFile(path.join(stage,'package.json'),'{"type":"module"}');
 for(const file of files){
  const bytes=Buffer.from(file.content,file.encoding||'utf8');
  if(createHash('sha256').update(bytes).digest('hex')!==file.sha256)throw Error('Integridade do reparo inválida: '+file.name);
  const target=path.join(stage,file.name);await mkdir(path.dirname(target),{recursive:true});await writeFile(target,bytes);
  if(file.name.endsWith('.sh'))execFileSync('bash',['-n',target],{stdio:'inherit'});
  else if(file.name.endsWith('.py'))execFileSync('python3',['-c','import pathlib,sys;compile(pathlib.Path(sys.argv[1]).read_text(),sys.argv[1],"exec")',target],{stdio:'inherit'});
  else if(file.name.endsWith('.js'))execFileSync(process.execPath,['--check',target],{stdio:'inherit'});
  else if(file.name.endsWith('.json'))JSON.parse(file.content);
 }
 const {installStaged}=await import(pathToFileURL(path.join(root,'scripts/phone-update.js')));
 const backup=path.join(root,'data/installer-backups',path.basename(stage));
 await installStaged(stage,root,{version:pkg.version,files:files.map(f=>f.name)},backup);
 console.log('Reparo SIGILL aplicado. Arquivos anteriores guardados em '+backup);
 console.log('Fontes APT, chaves, .env, progresso e modelos locais foram preservados.');
 console.log('Áudio incluído. Execute: bash local-ai.sh clone setup && bash local-ai.sh start');
} catch(error) {console.error('Reparo não concluído: '+error.message);process.exitCode=1;}
